css:
#mp4,#mp4b{display:block;width:100%;max-width:320px;margin:12px auto 0;aspect-ratio:9/16;background:#000;border-radius:12px;border:1px solid var(--line)}
.aud{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-top:10px;padding:8px 0;border-top:1px solid var(--line)}
.aud-name{display:flex;flex-direction:column;min-width:90px}
.aud-name span{color:var(--muted);font-size:.8rem}
.aud audio{flex:1 1 200px;min-width:0;max-width:100%}
